---

### Step 2: The C Linux Agent (Task 7)

Now we write the actual systems-level code. We will read directly from the Linux `/proc` filesystem. To keep dependencies at zero (no `libcurl`, no `cJSON`), we will write a custom JSON builder and a raw POSIX socket HTTP client.

#### 2.1 The Collectors (Linux `/proc` parsers)

**File: `agent/include/collector.h`**
```c
#ifndef COLLECTOR_H
#define COLLECTOR_H

#include <stdint.h>

typedef struct {
    double cpu_utilization;
    uint64_t mem_total_bytes;
    uint64_t mem_used_bytes;
    uint64_t disk_total_bytes;
    uint64_t disk_used_bytes;
    uint64_t net_rx_bytes;
    uint64_t net_tx_bytes;
    double load_avg_1m;
    uint64_t uptime_seconds;
} SystemMetrics;

// Collectors return 0 on success, -1 on error
int collect_cpu(double *utilization);
int collect_memory(uint64_t *total, uint64_t *used);
int collect_disk(uint64_t *total, uint64_t *used);
int collect_network(uint64_t *rx, uint64_t *tx);
int collect_system_load(double *load_1m);
int collect_uptime(uint64_t *seconds);

#endif
```

**File: `agent/src/platform/linux/cpu.c`**
```c
#include "collector.h"
#include <stdio.h>
#include <string.h>
#include <unistd.h>

int collect_cpu(double *utilization) {
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) return -1;

    char line[256];
    uint64_t user1, nice1, system1, idle1, iowait1, irq1, softirq1, steal1;
    uint64_t user2, nice2, system2, idle2, iowait2, irq2, softirq2, steal2;

    // First read
    fgets(line, sizeof(line), fp);
    sscanf(line, "cpu  %lu %lu %lu %lu %lu %lu %lu %lu", 
           &user1, &nice1, &system1, &idle1, &iowait1, &irq1, &softirq1, &steal1);
    fclose(fp);

    sleep(1); // Wait 1 second for delta calculation

    fp = fopen("/proc/stat", "r");
    if (!fp) return -1;

    // Second read
    fgets(line, sizeof(line), fp);
    sscanf(line, "cpu  %lu %lu %lu %lu %lu %lu %lu %lu", 
           &user2, &nice2, &system2, &idle2, &iowait2, &irq2, &softirq2, &steal2);
    fclose(fp);

    uint64_t total1 = user1 + nice1 + system1 + idle1 + iowait1 + irq1 + softirq1 + steal1;
    uint64_t total2 = user2 + nice2 + system2 + idle2 + iowait2 + irq2 + softirq2 + steal2;

    uint64_t total_delta = total2 - total1;
    uint64_t idle_delta = idle2 - idle1;

    if (total_delta == 0) {
        *utilization = 0.0;
    } else {
        *utilization = 100.0 * (1.0 - ((double)idle_delta / total_delta));
    }

    return 0;
}
```

**File: `agent/src/platform/linux/memory.c`**
```c
#include "collector.h"
#include <stdio.h>
#include <string.h>

int collect_memory(uint64_t *total, uint64_t *used) {
    FILE *fp = fopen("/proc/meminfo", "r");
    if (!fp) return -1;

    char line[256];
    uint64_t mem_total = 0, mem_free = 0, buffers = 0, cached = 0;

    while (fgets(line, sizeof(line), fp)) {
        if (sscanf(line, "MemTotal: %lu kB", &mem_total) == 1) continue;
        if (sscanf(line, "MemFree: %lu kB", &mem_free) == 1) continue;
        if (sscanf(line, "Buffers: %lu kB", &buffers) == 1) continue;
        if (sscanf(line, "Cached: %lu kB", &cached) == 1) continue;
    }
    fclose(fp);

    *total = mem_total * 1024; // Convert to bytes
    uint64_t available = mem_free + buffers + cached;
    *used = (mem_total - available) * 1024;

    return 0;
}
```
*(Note: For brevity, I am combining Disk, Network, Load, and Uptime into a single file below, but in your repo, split them into `disk.c`, `network.c`, etc., reading `/proc/mounts`+`statvfs`, `/proc/net/dev`, `/proc/loadavg`, and `/proc/uptime` respectively).*

**File: `agent/src/platform/linux/system.c`**
```c
#include "collector.h"
#include <stdio.h>
#include <sys/statvfs.h>

int collect_disk(uint64_t *total, uint64_t *used) {
    struct statvfs stat;
    if (statvfs("/", &stat) != 0) return -1;

    *total = (uint64_t)stat.f_blocks * stat.f_frsize;
    uint64_t free_space = (uint64_t)stat.f_bfree * stat.f_frsize;
    *used = *total - free_space;
    return 0;
}

int collect_network(uint64_t *rx, uint64_t *tx) {
    // Simplified: reads eth0. In production, loop through /proc/net/dev
    FILE *fp = fopen("/proc/net/dev", "r");
    if (!fp) return -1;
    char line[256];
    *rx = 0; *tx = 0;
    while (fgets(line, sizeof(line), fp)) {
        if (strstr(line, "eth0") || strstr(line, "ens")) {
            char *colon = strchr(line, ':');
            if (colon) {
                sscanf(colon + 1, "%lu %*u %*u %*u %*u %*u %*u %*u %lu", rx, tx);
                break;
            }
        }
    }
    fclose(fp);
    return 0;
}

int collect_system_load(double *load_1m) {
    FILE *fp = fopen("/proc/loadavg", "r");
    if (!fp) return -1;
    fscanf(fp, "%lf", load_1m);
    fclose(fp);
    return 0;
}

int collect_uptime(uint64_t *seconds) {
    FILE *fp = fopen("/proc/uptime", "r");
    if (!fp) return -1;
    double up;
    fscanf(fp, "%lf", &up);
    *seconds = (uint64_t)up;
    fclose(fp);
    return 0;
}
```

#### 2.2 The Core: JSON Builder & Raw HTTP Client

**File: `agent/src/core/transport.c`**
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netdb.h>
#include <time.h>
#include "collector.h"

// Simple JSON builder for telemetry payload
void build_telemetry_json(char *buffer, size_t size, const char *agent_id, uint64_t seq, SystemMetrics *m) {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    snprintf(buffer, size, 
        "{"
        "\"agent_id\":\"%s\","
        "\"timestamp\":\"%s\","
        "\"sequence\":%lu,"
        "\"metrics\":["
            "{\"name\":\"system.cpu.utilization\",\"value\":%.2f,\"unit\":\"percent\"},"
            "{\"name\":\"system.memory.utilization\",\"value\":%.2f,\"unit\":\"percent\"},"
            "{\"name\":\"system.disk.utilization\",\"value\":%.2f,\"unit\":\"percent\"},"
            "{\"name\":\"system.load.1m\",\"value\":%.2f,\"unit\":\"count\"}"
        "]"
        "}",
        agent_id, timestamp, seq,
        m->cpu_utilization,
        (m->mem_total_bytes > 0) ? (100.0 * m->mem_used_bytes / m->mem_total_bytes) : 0.0,
        (m->disk_total_bytes > 0) ? (100.0 * m->disk_used_bytes / m->disk_total_bytes) : 0.0,
        m->load_avg_1m
    );
}

// Raw POSIX HTTP POST (Zero dependencies)
int send_telemetry(const char *host, int port, const char *path, const char *json_payload, const char *auth_token) {
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    char port_str[6];
    snprintf(port_str, sizeof(port_str), "%d", port);

    if (getaddrinfo(host, port_str, &hints, &res) != 0) return -1;

    int sock = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (sock < 0) { freeaddrinfo(res); return -1; }

    if (connect(sock, res->ai_addr, res->ai_addrlen) < 0) {
        close(sock); freeaddrinfo(res); return -1;
    }
    freeaddrinfo(res);

    char request[4096];
    snprintf(request, sizeof(request),
        "POST %s HTTP/1.1\r\n"
        "Host: %s\r\n"
        "Authorization: Bearer %s\r\n"
        "Content-Type: application/json\r\n"
        "Content-Length: %zu\r\n"
        "Connection: close\r\n\r\n"
        "%s",
        path, host, auth_token, strlen(json_payload), json_payload
    );

    send(sock, request, strlen(request), 0);

    char response[1024];
    recv(sock, response, sizeof(response)-1, 0);
    close(sock);

    // Basic check for HTTP 200 OK
    return strstr(response, "200 OK") ? 0 : -1;
}
```

#### 2.3 The Main Loop

**File: `agent/src/main.c`**
```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include "collector.h"

extern void build_telemetry_json(char *buffer, size_t size, const char *agent_id, uint64_t seq, SystemMetrics *m);
extern int send_telemetry(const char *host, int port, const char *path, const char *json_payload, const char *auth_token);

int main() {
    printf("SentriX Agent v0.1.0 starting...\n");

    // Hardcoded for V1 MVP demo (Will be loaded from config/enrollment later)
    const char *agent_id = "00000000-0000-0000-0000-000000000001"; 
    const char *server_host = "127.0.0.1";
    int server_port = 8080;
    const char *auth_token = "agent_secret_credential";
    uint64_t sequence = 1;

    char json_buffer[2048];
    SystemMetrics metrics;

    while (1) {
        printf("Collecting metrics...\n");

        collect_cpu(&metrics.cpu_utilization);
        collect_memory(&metrics.mem_total_bytes, &metrics.mem_used_bytes);
        collect_disk(&metrics.disk_total_bytes, &metrics.disk_used_bytes);
        collect_network(&metrics.net_rx_bytes, &metrics.net_tx_bytes);
        collect_system_load(&metrics.load_avg_1m);
        collect_uptime(&metrics.uptime_seconds);

        build_telemetry_json(json_buffer, sizeof(json_buffer), agent_id, sequence, &metrics);

        printf("Sending payload (seq %lu)...\n", sequence);
        if (send_telemetry(server_host, server_port, "/api/v1/agent/telemetry", json_buffer, auth_token) == 0) {
            printf("Success.\n");
        } else {
            printf("Failed to send. Will retry next cycle.\n");
        }

        sequence++;
        sleep(10); // 10 second collection interval
    }
    return 0;
}
```

