### Step 3: Go Backend Ingestion & Enrollment (Task 8)

Now we update the Go server to accept this data. We need an **Enrollment Endpoint** and a **Telemetry Ingestion Endpoint**.

**File: `server/internal/agents/handler.go`**
```go
package agents

import (
	"encoding/json"
	"net/http"
	"time"

	"github.com/go-chi/chi/v5"
	"github.com/google/uuid"
	"github.com/jackc/pgx/v5/pgxpool"
)

type EnrollmentRequest struct {
	Token          string `json:"token" validate:"required"`
	Hostname       string `json:"hostname" validate:"required"`
	Platform       string `json:"platform" validate:"required"`
	Architecture   string `json:"architecture" validate:"required"`
	AgentVersion   string `json:"agent_version" validate:"required"`
}

type EnrollmentResponse struct {
	AgentID    string `json:"agent_id"`
	Credential string `json:"credential"`
	ServerURL  string `json:"server_url"`
}

// POST /api/v1/agent/enroll
func HandleEnroll(pool *pgxpool.Pool) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		var req EnrollmentRequest
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			http.Error(w, "Invalid JSON", http.StatusBadRequest)
			return
		}

		// 1. Validate Token (In V1, we just check if it exists in a dummy table or env var)
		// For MVP, let's accept a hardcoded master token or check DB.
		if req.Token != "SENTRIX_MASTER_ENROLLMENT_TOKEN" {
			http.Error(w, "Invalid enrollment token", http.StatusUnauthorized)
			return
		}

		// 2. Generate Agent ID and Credential
		agentID := uuid.New().String()
		credential := uuid.New().String() // In production, use a secure random generator

		// 3. Insert into DB
		ctx := r.Context()
		serverID := uuid.New().String()

		_, err := pool.Exec(ctx, `
			INSERT INTO agents (id, name, credential_hash, status) 
			VALUES ($1, $2, $3, 'ACTIVE')
		`, agentID, req.Hostname, credential) // Note: Hash the credential in production!

		if err != nil {
			http.Error(w, "Database error", http.StatusInternalServerError)
			return
		}

		_, err = pool.Exec(ctx, `
			INSERT INTO servers (id, agent_id, name, hostname, platform, architecture, agent_version, status, registered_at) 
			VALUES ($1, $2, $3, $4, $5, $6, $7, 'ONLINE', NOW())
		`, serverID, agentID, req.Hostname, req.Hostname, req.Platform, req.Architecture, req.AgentVersion)

		if err != nil {
			http.Error(w, "Database error", http.StatusInternalServerError)
			return
		}

		// 4. Return credentials
		resp := EnrollmentResponse{
			AgentID:    agentID,
			Credential: credential,
			ServerURL:  "http://127.0.0.1:8080",
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(resp)
	}
}
```

**File: `server/internal/metrics/handler.go`**
```go
package metrics

import (
	"context"
	"encoding/json"
	"net/http"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

type TelemetryPayload struct {
	AgentID   string    `json:"agent_id"`
	Timestamp time.Time `json:"timestamp"`
	Sequence  int64     `json:"sequence"`
	Metrics   []Metric  `json:"metrics"`
}

type Metric struct {
	Name   string            `json:"name"`
	Value  float64           `json:"value"`
	Unit   string            `json:"unit"`
	Labels map[string]string `json:"labels,omitempty"`
}

// Middleware to validate Agent Bearer Token
func AgentAuthMiddleware(pool *pgxpool.Pool, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		authHeader := r.Header.Get("Authorization")
		if len(authHeader) < 7 || authHeader[:7] != "Bearer " {
			http.Error(w, "Unauthorized", http.StatusUnauthorized)
			return
		}
		credential := authHeader[7:]

		var agentID string
		err := pool.QueryRow(r.Context(), "SELECT id FROM agents WHERE credential_hash = $1 AND status = 'ACTIVE'", credential).Scan(&agentID)
		if err != nil {
			http.Error(w, "Invalid credential", http.StatusUnauthorized)
			return
		}

		// Inject agent_id into context for the handler
		ctx := context.WithValue(r.Context(), "agent_id", agentID)
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

// POST /api/v1/agent/telemetry
func HandleTelemetry(pool *pgxpool.Pool) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		agentID := r.Context().Value("agent_id").(string)

		var payload TelemetryPayload
		if err := json.NewDecoder(r.Body).Decode(&payload); err != nil {
			http.Error(w, "Invalid JSON", http.StatusBadRequest)
			return
		}

		// Override timestamp with server time to prevent clock skew issues, or use payload timestamp
		ts := payload.Timestamp
		if ts.IsZero() {
			ts = time.Now()
		}

		// Get Server ID from Agent ID
		var serverID string
		err := pool.QueryRow(r.Context(), "SELECT id FROM servers WHERE agent_id = $1", agentID).Scan(&serverID)
		if err != nil {
			http.Error(w, "Server not found for agent", http.StatusNotFound)
			return
		}

		// Batch insert into TimescaleDB
		batch := &pgx.Batch{}

		for _, m := range payload.Metrics {
			var tableName string
			switch m.Name {
			case "system.cpu.utilization":
				tableName = "metric_cpu"
			case "system.memory.utilization":
				tableName = "metric_memory"
			case "system.disk.utilization":
				tableName = "metric_disk"
			default:
				continue // Ignore unknown metrics for now
			}

			query := "INSERT INTO " + tableName + " (time, server_id, value) VALUES ($1, $2, $3)"
			batch.Queue(query, ts, serverID, m.Value)
		}

		// Update last_seen_at for the server
		batch.Queue("UPDATE servers SET last_seen_at = $1, status = 'ONLINE' WHERE id = $2", time.Now(), serverID)

		br := pool.SendBatch(r.Context(), batch)
		if _, err := br.Exec(); err != nil {
			http.Error(w, "Database write error", http.StatusInternalServerError)
			return
		}
		br.Close()

		w.WriteHeader(http.StatusAccepted)
		w.Write([]byte(`{"status": "accepted"}`))
	}
}
```

