import { FormEvent, useState } from 'react';

import { useServers } from '../../hooks/useDashboard';
import {
  CreateCheckInput,
  useChecks,
  useCreateCheck,
  useDeleteCheck,
} from '../../hooks/useChecks';

const checkTypes = ['PROCESS', 'SERVICE', 'PORT', 'COMMAND'];

export function ChecksPage() {
  const { data: checks, isLoading: checksLoading } = useChecks();
  const { data: servers } = useServers();

  const createCheck = useCreateCheck();
  const deleteCheck = useDeleteCheck();

  const [serverId, setServerId] = useState('');
  const [type, setType] = useState('PROCESS');
  const [name, setName] = useState('');
  const [severity, setSeverity] = useState('WARNING');

  const [processName, setProcessName] = useState('');
  const [serviceUnit, setServiceUnit] = useState('');
  const [host, setHost] = useState('127.0.0.1');
  const [port, setPort] = useState(80);
  const [command, setCommand] = useState('');
  const [commandArgs, setCommandArgs] = useState('');

  const [error, setError] = useState<string | null>(null);

  async function handleSubmit(event: FormEvent) {
    event.preventDefault();

    setError(null);

    if (!serverId) {
      setError('Select a server.');
      return;
    }

    if (!name) {
      setError('Check name is required.');
      return;
    }

    const config: Record<string, any> = {};

    if (type === 'PROCESS') {
      if (!processName) {
        setError('Process name is required.');
        return;
      }

      config.name = processName;
    }

    if (type === 'SERVICE') {
      if (!serviceUnit) {
        setError('Service unit is required.');
        return;
      }

      config.unit = serviceUnit;
    }

    if (type === 'PORT') {
      if (!host) {
        setError('Host is required.');
        return;
      }

      config.host = host;
      config.port = Number(port);
    }

    if (type === 'COMMAND') {
      if (!command) {
        setError('Command is required.');
        return;
      }

      config.command = command;
      config.args = commandArgs
        .split(',')
        .map((item) => item.trim())
        .filter(Boolean);
    }

    const payload: CreateCheckInput = {
      server_id: serverId,
      type,
      name,
      enabled: true,
      interval_seconds: 15,
      timeout_seconds: 5,
      failure_threshold: 3,
      success_threshold: 1,
      severity,
      config,
    };

    try {
      await createCheck.mutateAsync(payload);

      setName('');
      setProcessName('');
      setServiceUnit('');
      setCommand('');
      setCommandArgs('');
    } catch {
      setError('Failed to create check.');
    }
  }

  function stateColor(state: string | null) {
    switch (state) {
      case 'OK':
        return 'bg-healthy';
      case 'PENDING':
        return 'bg-warning';
      case 'FAILING':
        return 'bg-critical';
      default:
        return 'bg-offline';
    }
  }

  return (
    <div className="max-w-7xl mx-auto space-y-8">
      <div>
        <h1 className="text-2xl font-bold text-white">Checks</h1>
        <p className="text-sm text-muted mt-1">
          Process, service, port, and command health checks.
        </p>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
        {/* Create form */}
        <div className="xl:col-span-1 bg-surface border border-border rounded-lg p-6">
          <h2 className="text-base font-semibold text-white mb-4">
            Create check
          </h2>

          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="block text-xs text-muted mb-1">Server</label>
              <select
