int main(void) {
    printf("SentriX Agent v0.2.0 starting...\n");

    // Replace these with enrollment response values.
    const char *agent_id = "YOUR_AGENT_ID";
    const char *auth_token = "YOUR_AGENT_CREDENTIAL";

    const char *server_host = "127.0.0.1";
    int server_port = 8080;

    char json_buffer[2048];
    SystemMetrics metrics;

    uint64_t sequence = 1;

    time_t last_metrics = 0;
    time_t last_checks = 0;

    while (1) {
        time_t now = time(NULL);

        if (now - last_metrics >= 10) {
            collect_cpu(&metrics.cpu_utilization);
            collect_memory(&metrics.mem_total_bytes, &metrics.mem_used_bytes);
            collect_disk(&metrics.disk_total_bytes, &metrics.disk_used_bytes);
            collect_network(&metrics.net_rx_bytes, &metrics.net_tx_bytes);
            collect_system_load(&metrics.load_avg_1m);
            collect_uptime(&metrics.uptime_seconds);

            build_telemetry_json(
                json_buffer,
                sizeof(json_buffer),
                agent_id,
                sequence,
                &metrics
            );

            send_telemetry(
                server_host,
                server_port,
                "/api/v1/agent/telemetry",
                json_buffer,
                auth_token
            );

            sequence++;
            last_metrics = now;
        }

        if (now - last_checks >= 15) {
            run_checks_cycle(
                server_host,
                server_port,
                agent_id,
                auth_token
            );

            last_checks = now;
        }

        sleep(5);
    }

    return 0;
}
