#### 1.1 Dashboard Summary Handler

**File: `server/internal/health/handler.go`**
```go
package health

import (
	"encoding/json"
	"net/http"

	"github.com/jackc/pgx/v5/pgxpool"
)

type DashboardSummary struct {
	Servers   ServerCounts   `json:"servers"`
	Incidents IncidentCounts `json:"incidents"`
}

type ServerCounts struct {
	Total    int `json:"total"`
	Online   int `json:"online"`
	Suspect  int `json:"suspect"`
	Offline  int `json:"offline"`
}

type IncidentCounts struct {
	Open     int `json:"open"`
	Critical int `json:"critical"`
}

// GET /api/v1/dashboard/summary
func HandleDashboardSummary(pool *pgxpool.Pool) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		ctx := r.Context()
		var summary DashboardSummary

		// 1. Get Server Counts (Computing status dynamically based on last_seen_at)
		err := pool.QueryRow(ctx, `
			SELECT 
				COUNT(*) as total,
				COUNT(*) FILTER (WHERE last_seen_at > NOW() - INTERVAL '30 seconds') as online,
				COUNT(*) FILTER (WHERE last_seen_at <= NOW() - INTERVAL '30 seconds' AND last_seen_at > NOW() - INTERVAL '60 seconds') as suspect,
				COUNT(*) FILTER (WHERE last_seen_at <= NOW() - INTERVAL '60 seconds') as offline
			FROM servers
		`).Scan(&summary.Servers.Total, &summary.Servers.Online, &summary.Servers.Suspect, &summary.Servers.Offline)

		if err != nil {
			http.Error(w, "Database error", http.StatusInternalServerError)
			return
		}

		// 2. Get Incident Counts
		err = pool.QueryRow(ctx, `
			SELECT 
				COUNT(*) FILTER (WHERE status = 'OPEN' OR status = 'ACKNOWLEDGED') as open,
				COUNT(*) FILTER (WHERE severity = 'CRITICAL' AND (status = 'OPEN' OR status = 'ACKNOWLEDGED')) as critical
			FROM incidents
		`).Scan(&summary.Incidents.Open, &summary.Incidents.Critical)

		if err != nil {
			http.Error(w, "Database error", http.StatusInternalServerError)
			return
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(summary)
	}
}
```

#### 1.2 Servers List Handler (with Latest Metrics)

To get the *latest* metric for each server efficiently, we use PostgreSQL's `LATERAL` joins. This is highly optimized in TimescaleDB.

**File: `server/internal/servers/handler.go`**
```go
package servers

import (
	"encoding/json"
	"net/http"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
)

type ServerListItem struct {
	ID          string    `json:"id"`
	Name        string    `json:"name"`
	Hostname    string    `json:"hostname"`
	Platform    string    `json:"platform"`
	Status      string    `json:"status"` // Computed: ONLINE, SUSPECT, OFFLINE
	LastSeen    time.Time `json:"last_seen"`
	CPU         *float64  `json:"cpu"`
	Memory      *float64  `json:"memory"`
	Disk        *float64  `json:"disk"`
}

// GET /api/v1/servers
func HandleListServers(pool *pgxpool.Pool) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		ctx := r.Context()

		// We compute the status dynamically based on heartbeat timeout
		rows, err := pool.Query(ctx, `
			SELECT 
				s.id, s.name, s.hostname, s.platform, s.last_seen_at,
				CASE 
					WHEN s.last_seen_at > NOW() - INTERVAL '30 seconds' THEN 'ONLINE'
					WHEN s.last_seen_at > NOW() - INTERVAL '60 seconds' THEN 'SUSPECT'
					ELSE 'OFFLINE'
				END as status,
				c.value as cpu, m.value as memory, d.value as disk
			FROM servers s
			LEFT JOIN LATERAL (SELECT value FROM metric_cpu WHERE server_id = s.id ORDER BY time DESC LIMIT 1) c ON true
			LEFT JOIN LATERAL (SELECT value FROM metric_memory WHERE server_id = s.id ORDER BY time DESC LIMIT 1) m ON true
			LEFT JOIN LATERAL (SELECT value FROM metric_disk WHERE server_id = s.id ORDER BY time DESC LIMIT 1) d ON true
			ORDER BY s.name ASC
		`)
		if err != nil {
			http.Error(w, "Database error", http.StatusInternalServerError)
			return
		}
		defer rows.Close()

		var servers []ServerListItem
		for rows.Next() {
			var srv ServerListItem
			// Scan handles NULLs for metrics if a server has no data yet
			err := rows.Scan(&srv.ID, &srv.Name, &srv.Hostname, &srv.Platform, &srv.LastSeen, &srv.Status, &srv.CPU, &srv.Memory, &srv.Disk)
			if err != nil {
				http.Error(w, "Scan error", http.StatusInternalServerError)
				return
			}
			servers = append(servers, srv)
		}

		if servers == nil {
			servers = []ServerListItem{} // Return empty array, not null
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(servers)
	}
}
```

