# 1. Database Migration for Notifications + Auth

Create the third migration.

**File: `server/migrations/00003_notifications_auth.sql`**

```sql
-- Notification channels
CREATE TABLE IF NOT EXISTS notification_channels (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    type TEXT NOT NULL DEFAULT 'WEBHOOK' CHECK (type IN ('WEBHOOK')),
    name TEXT NOT NULL,
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    config JSONB NOT NULL DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Notification jobs / outbox
CREATE TABLE IF NOT EXISTS notification_jobs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    channel_id UUID NOT NULL REFERENCES notification_channels(id) ON DELETE CASCADE,
    event_type TEXT NOT NULL,
    alert_rule_id UUID REFERENCES alert_rules(id) ON DELETE SET NULL,
    server_id UUID REFERENCES servers(id) ON DELETE CASCADE,
