                  </Layout>
                </Protected>
              }
            />

            <Route
              path="/alerts"
              element={
                <Protected>
                  <Layout>
                    <AlertRulesPage />
                  </Layout>
                </Protected>
              }
            />
          </Routes>
        </BrowserRouter>
      </AuthProvider>
